/** Shared lexical rules for authored design names and dotted declaration paths. */
export declare const DESIGN_IDENTIFIER_SOURCE = "[A-Za-z_][A-Za-z0-9_]*";
export declare const AUTHORED_PATH_SEGMENT_SOURCE = "[A-Za-z_][A-Za-z0-9_-]*";
export declare function isDesignIdentifier(value: string): boolean;
export declare function isAuthoredPathSegment(value: string): boolean;
export declare function invalidAuthoredPathSegment(path: string): string | undefined;
export declare function isAuthoredDeclarationPath(path: string): boolean;
